/**
 * A statistic `aggregate()` can compute.
 *
 * @since 0.2.0
 */
export type AggregateMetric = 'sum' | 'avg' | 'min' | 'max' | 'count' | 'duration';

export interface RegistryUnit {
  /** Units of one type share a dimension. */
  dimension: string;
  /** HealthKit has this unit. */
  ios: boolean;
  /** Health Connect has this unit. */
  android: boolean;
}

export interface RegistryValueSet {
  /** Unified values, in display order. */
  values: readonly string[];
  /** Values HealthKit can store, or `null` when the set has no HealthKit mapping. */
  ios: readonly string[] | null;
  /** Values Health Connect can store, or `null` when the set has no Health Connect mapping. */
  android: readonly string[] | null;
}

export interface RegistryNutrient {
  /** Canonical unit: `g` or `kcal`. */
  unit: string;
  /** HealthKit dietary quantity identifier, or `null` when HealthKit has none. */
  ios: string | null;
  /** `NutritionRecord` property, or `null` when Health Connect has none. */
  android: string | null;
}

/** One child array of a session type (sleep stages, workout segments and laps). */
export interface RegistryPart {
  /** Value set of each child's type. */
  values?: string;
}

export interface RegistryField {
  type: 'boolean' | 'enum';
  /** Value set name, for enum fields. */
  values?: string;
  ios: boolean;
  /** `computed`: derived by the plugin on read, not stored on the record. */
  android: 'stored' | 'computed' | false;
  requiredOnWriteIos?: true;
}

export interface RegistryEntry {
  id: HealthType;
  kind: RegistryKind;
  group: RegistryGroup;
  /** Value set name of the main value (category types). */
  values?: string;
  /** Canonical unit and the units callers may ask for (quantity types). */
  unit?: string;
  units?: readonly string[];
  fields?: Readonly<Record<string, RegistryField>>;
  /** Child arrays of a session type, by sample property. */
  parts?: Readonly<Record<string, RegistryPart>>;
  ios?: {
    /** Absent for combined ids (`members`). */
    identifier?: string;
    minOS: string;
    writable: boolean;
    /** `instant`: start must equal end. `interval`: end must be at least a second after start. */
    time: 'any' | 'instant' | 'interval';
    /** Values HealthKit accepts, in the type's only unit. */
    range?: { min: number; max: number };
    derivedFrom?: HealthType;
    /** Combined id: the split ids it reads together (decision #14). */
    members?: readonly HealthType[];
    /** Combined id: where writes go unless a sample names a member. */
    writeTo?: HealthType;
    /** No samples of its own; only `aggregate()` serves it. */
    aggregateOnly?: true;
    /** `aggregate()` metrics HealthKit serves. */
    metrics?: readonly AggregateMetric[];
  };
  android?: {
    record: string;
    time: 'instant' | 'interval' | 'series';
    readPermission: string;
    writePermission: string;
    writable: boolean;
    feature?: string;
    maxDurationDays?: number;
    /** No readable records; only `aggregate()` serves it. */
    aggregateOnly?: true;
    /** The record stores a whole number. */
    wholeNumber?: true;
    /** `aggregate()` metrics Health Connect serves. */
    metrics?: readonly AggregateMetric[];
  };
}

